/// a word of the field-of-view body: as is, `adrp x16, state`, `bl tanf`, `bl atanf`, or one of the three the caller supplies
#[derive(Clone, Copy)]
enum F {
    W(u32),
    Adrp,
    Tanf,
    Atanf,
    Ratio,
    HalfToS0,
    S0ToHalf,
}

// the instruction words are kept in the rows of the original (rustfmt would put one per line)
#[rustfmt::skip]
const FOV_BODY: [F; 35] = [
    F::Adrp, F::W(0xbd405a01), F::W(0x1e202028), F::W(0x540003e0), F::Ratio, F::W(0x1e213842), F::W(0x1e20c042), F::W(0xbd406203), F::W(0x1e232040), F::W(0x5400032a),
    F::W(0xb940a269), F::W(0x9104020a), F::W(0x5280080b), F::W(0xb840454c), F::W(0x6b09019f), F::W(0x54000260), F::W(0x7100056b), F::W(0x54ffff81),
    F::HalfToS0, F::Tanf, F::Adrp, F::W(0xbd405e01), F::W(0x1e210800), F::Atanf, F::S0ToHalf, F::W(0x1e202800), F::W(0xbd00a260),
    F::Adrp, F::W(0xb940fe0b), F::W(0x1200156c), F::W(0x1100056b), F::W(0xb900fe0b), F::W(0x9104020a), F::W(0xbc2c5940), F::HalfToS0,
];

const TANF: i64 = 0x159ff60;
const ATANF: i64 = 0x15a0070;
const DUO_SIZE: i64 = 0x25b4;

/// `bl` as the Python writes it: `B(here, to) | 0x80000000`
fn bl_to(ctx: &StubCtx, to: i64) -> Res<u32> {
    Ok(b(ctx.here(), to)? | 0x80000000)
}

fn adrp_state(ctx: &mut StubCtx, reg: u32) -> Res<()> {
    let w = asm::adrp(reg, ctx.here(), ctx.state)?;
    ctx.emit(w);
    Ok(())
}

fn emit_b(ctx: &mut StubCtx, to: i64) -> Res<()> {
    let w = b(ctx.here(), to)?;
    ctx.emit(w);
    Ok(())
}

fn put_b(ctx: &mut StubCtx, site: i64, start: i64, why: &str) -> Res<()> {
    let w = b(site, start)?;
    ctx.put(site, &[w], why);
    Ok(())
}

/// `vt(r, off)`: `adrp xR, off; add xR, xR, #off & 0xfff`
fn vt(ctx: &mut StubCtx, r: u32, off: i64) -> Res<()> {
    let w = asm::adrp(r, ctx.here(), off)?;
    ctx.emit(w);
    ctx.emit(addi(r, r, (off & 0xfff) as u32, 0));
    Ok(())
}

/// `taller(site, orig, load, apply, why)`
fn taller(ctx: &mut StubCtx, site: i64, orig: &str, load: u32, apply: u32, why: &str) -> Res<()> {
    ctx.site(site, orig)?;
    let start = ctx.here();
    ctx.emit(orig_word(orig));
    adrp_state(ctx, 16)?;
    for w in [load, 0x34000050, apply] {
        ctx.emit(w);
    }
    emit_b(ctx, site + 4)?;
    put_b(ctx, site, start, why)
}

/// `taller_bit(site, orig, bit, load, apply, why)`: the same behind the test of one bit of the sites mask (+0x54)
fn taller_bit(
    ctx: &mut StubCtx,
    site: i64,
    orig: &str,
    bit: u32,
    load: u32,
    apply: u32,
    why: &str,
) -> Res<()> {
    ctx.site(site, orig)?;
    let start = ctx.here();
    ctx.emit(orig_word(orig));
    adrp_state(ctx, 16)?;
    ctx.emit(0xb9405610);
    ctx.emit(0x36000000 | bit << 19 | 5 << 5 | 16);
    adrp_state(ctx, 16)?;
    for w in [load, 0x34000050, apply] {
        ctx.emit(w);
    }
    emit_b(ctx, site + 4)?;
    put_b(ctx, site, start, why)
}

/// `fov_stub(site, orig, aspect_word, half_to_s0, s0_to_half)`
fn fov_stub(
    ctx: &mut StubCtx,
    site: i64,
    orig: &str,
    aspect_word: u32,
    half_to_s0: u32,
    s0_to_half: u32,
) -> Res<()> {
    ctx.site(site, orig)?;
    let start = ctx.here();
    for f in FOV_BODY {
        match f {
            F::Adrp => adrp_state(ctx, 16)?,
            F::Tanf => {
                let w = bl_to(ctx, TANF)?;
                ctx.emit(w);
            }
            F::Atanf => {
                let w = bl_to(ctx, ATANF)?;
                ctx.emit(w);
            }
            F::W(w) => ctx.emit(w),
            F::Ratio => ctx.emit(aspect_word),
            F::HalfToS0 => ctx.emit(half_to_s0),
            F::S0ToHalf => ctx.emit(s0_to_half),
        }
    }
    emit_b(ctx, site + 4)?;
    put_b(
        ctx,
        site,
        start,
        "sead::PerspectiveProjection fovy widened for a view of the screen's ratio (more above and below, 16:9 sides), stored widened",
    )
}

/// `cam_fovy(site, orig, x8_page, why)`
fn cam_fovy(ctx: &mut StubCtx, site: i64, orig: &str, x8_page: i64, why: &str) -> Res<()> {
    ctx.site(site, orig)?;
    let back: u32 = if x8_page != 0 { 17 } else { 16 };
    let start = ctx.here();
    ctx.emit(orig_word(orig));
    adrp_state(ctx, 16)?;
    for w in [
        0xbd405a01u32,
        0x1e202028,
        0x54000000 | (back - 4) << 5,
        0xbd406201,
        0x1e202028,
        0x54000004 | (back - 7) << 5,
        0x1e2c1001,
        0x1e210800,
    ] {
        ctx.emit(w);
    }
    let w = bl_to(ctx, TANF)?;
    ctx.emit(w);
    adrp_state(ctx, 16)?;
    ctx.emit(0xbd405e01);
    ctx.emit(0x1e210800);
    let w = bl_to(ctx, ATANF)?;
    ctx.emit(w);
    ctx.emit(0x1e202800);
    if x8_page != 0 {
        let w = asm::adrp(8, ctx.here(), x8_page)?;
        ctx.emit(w);
    }
    emit_b(ctx, site + 4)?;
    put_b(ctx, site, start, why)
}

